// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(address sender, uint256 depositAmount, uint256 withdrawAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0 && withdrawAmount > depositAmount && msg.sender == sender);
        try c.deposit{value: depositAmount}() {} catch { return; }
        bool reverted;
        try c.withdraw(withdrawAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == true);
    }

    function testFuzz_run(address sender, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(uint160(sender) > 255 && sender != address(this) && sender != address(c) && sender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && sender != 0x000000000000000000636F6e736F6c652e6c6f67 && sender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && sender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(sender, depositAmount, withdrawAmount);
    }

    receive() external payable {}
}
